function hllAdd(registers, x) {
  const h = hash64(x);
  const m = registers.length;
  const idx = h >>> (64 - Math.log2(m));
  const rho = leadingZeros((h << Math.log2(m)) | (h >>> (64 - Math.log2(m))) ) + 1;
  registers[idx] = Math.max(registers[idx], rho);
